import api from './api'

export interface BlogPost {
  id: string
  title: string
  content: string
  author: string
  createdAt: string
  updatedAt: string
  tags: string[]
  readCount: number
  likeCount: number
  commentCount: number
}

export interface CreateBlogRequest {
  title: string
  content: string
  tags: string[]
}

export interface UpdateBlogRequest extends Partial<CreateBlogRequest> {
  id: string
}

export const blogService = {
  // 获取博客列表
  getBlogs: async (page = 1, limit = 10): Promise<{ blogs: BlogPost[]; total: number }> => {
    const response = await api.get('/blogs', { params: { page, limit } })
    return response.data
  },

  // 获取单篇博客
  getBlogById: async (id: string): Promise<BlogPost> => {
    const response = await api.get(`/blogs/${id}`)
    return response.data
  },

  // 创建博客
  createBlog: async (data: CreateBlogRequest): Promise<BlogPost> => {
    const response = await api.post('/blogs', data)
    return response.data
  },

  // 更新博客
  updateBlog: async (data: UpdateBlogRequest): Promise<BlogPost> => {
    const response = await api.put(`/blogs/${data.id}`, data)
    return response.data
  },

  // 删除博客
  deleteBlog: async (id: string): Promise<void> => {
    await api.delete(`/blogs/${id}`)
  },

  // 搜索博客
  searchBlogs: async (query: string, page = 1, limit = 10): Promise<{ blogs: BlogPost[]; total: number }> => {
    const response = await api.get('/blogs/search', { params: { q: query, page, limit } })
    return response.data
  },

  // 点赞博客
  likeBlog: async (id: string): Promise<void> => {
    await api.post(`/blogs/${id}/like`)
  },

  // 取消点赞
  unlikeBlog: async (id: string): Promise<void> => {
    await api.delete(`/blogs/${id}/like`)
  },

  // 收藏博客
  favoriteBlog: async (id: string): Promise<void> => {
    await api.post(`/blogs/${id}/favorite`)
  },

  // 取消收藏
  unfavoriteBlog: async (id: string): Promise<void> => {
    await api.delete(`/blogs/${id}/favorite`)
  },
}

import { useState } from 'react'
import { useNavigate, Link } from 'react-router-dom'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { authService } from '@/services/auth'

export default function Login() {
  const navigate = useNavigate()
  const [formData, setFormData] = useState({ email: '', password: '' })
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    setLoading(true)

    try {
      // 模拟登录（因为后端尚未实现）
      if (formData.email && formData.password) {
        // 模拟 API 调用延迟
        await new Promise(resolve => setTimeout(resolve, 500))

        // 模拟成功登录
        const mockToken = 'mock-jwt-token'
        localStorage.setItem('token', mockToken)

        // 跳转到首页
        navigate('/')
      } else {
        setError('请输入邮箱和密码')
      }
    } catch (err) {
      setError('登录失败，请检查您的凭据')
    } finally {
      setLoading(false)
    }
  }

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({
      ...formData,
      [e.target.id]: e.target.value,
    })
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50">
      <div className="w-full max-w-md p-8 bg-white border rounded-lg shadow-lg">
        <h2 className="text-2xl font-bold mb-6 text-center">登录</h2>
        <form className="space-y-4" onSubmit={handleSubmit}>
          <div>
            <label htmlFor="email" className="block text-sm font-medium mb-1">
              邮箱
            </label>
            <Input
              id="email"
              type="email"
              placeholder="请输入邮箱"
              value={formData.email}
              onChange={handleChange}
              required
            />
          </div>
          <div>
            <label htmlFor="password" className="block text-sm font-medium mb-1">
              密码
            </label>
            <Input
              id="password"
              type="password"
              placeholder="请输入密码"
              value={formData.password}
              onChange={handleChange}
              required
            />
          </div>
          {error && (
            <div className="text-red-500 text-sm text-center">{error}</div>
          )}
          <Button type="submit" className="w-full" disabled={loading}>
            {loading ? '登录中...' : '登录'}
          </Button>
        </form>
        <p className="mt-4 text-center text-sm text-gray-600">
          还没有账号？{' '}
          <Link to="/register" className="text-blue-600 hover:underline font-medium">
            立即注册
          </Link>
        </p>
      </div>
    </div>
  )
}

import { useState } from 'react'
import { useNavigate, Link } from 'react-router-dom'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { authService } from '@/services/auth'

export default function Register() {
  const navigate = useNavigate()
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: '',
  })
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')

    // 验证密码匹配
    if (formData.password !== formData.confirmPassword) {
      setError('两次输入的密码不匹配')
      return
    }

    setLoading(true)

    try {
      // 模拟注册（因为后端尚未实现）
      if (formData.username && formData.email && formData.password) {
        // 模拟 API 调用延迟
        await new Promise(resolve => setTimeout(resolve, 500))

        // 模拟成功注册
        const mockToken = 'mock-jwt-token'
        localStorage.setItem('token', mockToken)

        // 跳转到首页
        navigate('/')
      } else {
        setError('请填写所有必填项')
      }
    } catch (err) {
      setError('注册失败，请稍后重试')
    } finally {
      setLoading(false)
    }
  }

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({
      ...formData,
      [e.target.id]: e.target.value,
    })
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50">
      <div className="w-full max-w-md p-8 bg-white border rounded-lg shadow-lg">
        <h2 className="text-2xl font-bold mb-6 text-center">注册</h2>
        <form className="space-y-4" onSubmit={handleSubmit}>
          <div>
            <label htmlFor="username" className="block text-sm font-medium mb-1">
              用户名
            </label>
            <Input
              id="username"
              placeholder="请输入用户名"
              value={formData.username}
              onChange={handleChange}
              required
            />
          </div>
          <div>
            <label htmlFor="email" className="block text-sm font-medium mb-1">
              邮箱
            </label>
            <Input
              id="email"
              type="email"
              placeholder="请输入邮箱"
              value={formData.email}
              onChange={handleChange}
              required
            />
          </div>
          <div>
            <label htmlFor="password" className="block text-sm font-medium mb-1">
              密码
            </label>
            <Input
              id="password"
              type="password"
              placeholder="请输入密码"
              value={formData.password}
              onChange={handleChange}
              required
            />
          </div>
          <div>
            <label htmlFor="confirmPassword" className="block text-sm font-medium mb-1">
              确认密码
            </label>
            <Input
              id="confirmPassword"
              type="password"
              placeholder="请再次输入密码"
              value={formData.confirmPassword}
              onChange={handleChange}
              required
            />
          </div>
          {error && (
            <div className="text-red-500 text-sm text-center">{error}</div>
          )}
          <Button type="submit" className="w-full" disabled={loading}>
            {loading ? '注册中...' : '注册'}
          </Button>
        </form>
        <p className="mt-4 text-center text-sm text-gray-600">
          已有账号？{' '}
          <Link to="/login" className="text-blue-600 hover:underline font-medium">
            立即登录
          </Link>
        </p>
      </div>
    </div>
  )
}

import { Navigate } from 'react-router-dom'
import { authService } from '@/services/auth'

interface ProtectedRouteProps {
  children: React.ReactNode
}

export default function ProtectedRoute({ children }: ProtectedRouteProps) {
  if (!authService.isAuthenticated()) {
    return <Navigate to="/login" replace />
  }
  return <>{children}</>
}

