  const [searchQuery, setSearchQuery] = useState('')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)

  const fetchBlogs = async () => {
    setLoading(true)
    try {
      // 模拟 API 调用
      await new Promise(resolve => setTimeout(resolve, 500))
      const mockBlogs = Array.from({ length: 12 }).map((_, i) => ({
        id: `${i + 1}`,
        title: `博客文章标题 ${i + 1}`,
        content: `这是第 ${i + 1} 篇博客的内容摘要，这里会显示一些简要的介绍信息。`,
        author: `作者 ${(i % 5) + 1}`,
        createdAt: `2024-01-${String(i + 1).padStart(2, '0')}`,
        tags: ['React', 'TypeScript', '前端'].slice(0, (i % 3) + 1),
        readCount: Math.floor(Math.random() * 1000),
        likeCount: Math.floor(Math.random() * 100),
        commentCount: Math.floor(Math.random() * 50),
      }))
      setBlogs(mockBlogs)
      setTotalPages(3)
    } catch (error) {
      console.error('获取博客失败:', error)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchBlogs()
  }, [page])

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault()
    // 模拟搜索
    fetchBlogs()
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="mb-8">
        <h1 className="text-3xl font-bold mb-4">所有博客</h1>
        <p className="text-gray-600 mb-6">
          浏览所有博客文章，按时间倒序排列。
        </p>
        <form onSubmit={handleSearch} className="flex gap-2 mb-6">
          <Input
            placeholder="搜索博客标题或内容..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="flex-1"
          />
          <Button type="submit">搜索</Button>
        </form>
      </div>

      {loading ? (
        <div className="text-center py-12">加载中...</div>
      ) : (
        <>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {blogs.map(blog => (
              <Card key={blog.id} className="hover:shadow-lg transition-shadow">
                <CardHeader>
                  <CardTitle>
                    <Link to={`/blogs/${blog.id}`} className="hover:text-primary">
                      {blog.title}
                    </Link>
                  </CardTitle>
                  <CardDescription>
                    作者：{blog.author} · 发布日期：{blog.createdAt}
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <p className="text-gray-700 line-clamp-2">{blog.content}</p>
                  <div className="flex flex-wrap gap-2 mt-4">
                    {blog.tags.map((tag: string) => (
                      <Badge key={tag} variant="secondary">
                        {tag}
                      </Badge>
                    ))}
                  </div>
                </CardContent>
                <CardFooter className="flex justify-between text-sm text-gray-500">
                  <span>👁️ {blog.readCount} 阅读</span>
                  <span>❤️ {blog.likeCount} 点赞</span>
                  <span>💬 {blog.commentCount} 评论</span>
                </CardFooter>
              </Card>
            ))}
          </div>

          <div className="mt-8">
            <Pagination>
              <PaginationContent>
                <PaginationItem>
                  <PaginationPrevious 
                    onClick={() => setPage(p => Math.max(1, p - 1))}
                    className={page === 1 ? 'pointer-events-none opacity-50' : ''}
                  />
                </PaginationItem>
                {[...Array(totalPages)].map((_, i) => (
                  <PaginationItem key={i}>
                    <PaginationLink 
                      onClick={() => setPage(i + 1)}
                      isActive={page === i + 1}
                    >
                      {i + 1}
                    </PaginationLink>
                  </PaginationItem>
                ))}
                <PaginationItem>
                  <PaginationNext 
                    onClick={() => setPage(p => p + 1)}
                    className={page === totalPages ? 'pointer-events-none opacity-50' : ''}
                  />
                </PaginationItem>
              </PaginationContent>
            </Pagination>
          </div>
        </>
      )}
    </div>
  )
}

