import { Label } from '@/components/ui/label'
import { Badge } from '@/components/ui/badge'
import { X } from 'lucide-react'

export default function BlogEdit() {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const [title, setTitle] = useState('')
  const [content, setContent] = useState('')
  const [tagInput, setTagInput] = useState('')
  const [tags, setTags] = useState<string[]>([])
  const [category, setCategory] = useState('')
  const [isDraft, setIsDraft] = useState(false)
  const [loading, setLoading] = useState(false)
  const [fetching, setFetching] = useState(true)

  // 模拟加载博客数据
  useEffect(() => {
    const fetchBlog = async () => {
      setFetching(true)
      try {
        // 模拟 API 调用
        await new Promise(resolve => setTimeout(resolve, 500))
        // 模拟数据
        setTitle(`博客文章标题 ${id}`)
        setContent(`这是博客 ${id} 的内容。你可以在此编辑博客内容。支持 Markdown 格式。`)
        setTags(['React', 'TypeScript', '前端'])
        setCategory('技术')
        setIsDraft(false)
      } catch (error) {
        console.error('加载博客失败:', error)
        alert('加载博客失败')
      } finally {
        setFetching(false)
      }
    }
    if (id) {
      fetchBlog()
    }
  }, [id])

  const handleAddTag = () => {
    if (tagInput.trim() && !tags.includes(tagInput.trim())) {
      setTags([...tags, tagInput.trim()])
      setTagInput('')
    }
  }

  const handleRemoveTag = (tagToRemove: string) => {
    setTags(tags.filter(tag => tag !== tagToRemove))
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    try {
      // 模拟 API 调用
      await new Promise(resolve => setTimeout(resolve, 800))
      console.log('更新博客:', { id, title, content, tags, category, isDraft })
      alert(isDraft ? '博客已保存为草稿' : '博客更新成功')
      navigate('/my-blogs')
    } catch (error) {
      console.error('更新失败:', error)
      alert('更新失败，请重试')
    } finally {
      setLoading(false)
    }
  }

  if (fetching) {
    return (
      <div className="container mx-auto px-4 py-8 text-center">
        加载博客中...
      </div>
    )
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <Card className="max-w-3xl mx-auto">
        <CardHeader>
          <CardTitle>编辑博客</CardTitle>
          <CardDescription>修改博客内容，可以选择发布或保存为草稿</CardDescription>
        </CardHeader>
        <form onSubmit={handleSubmit}>
          <CardContent className="space-y-6">
            <div className="space-y-2">
              <Label htmlFor="title">标题</Label>
              <Input
                id="title"
                placeholder="请输入博客标题"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="category">分类</Label>
              <Input
                id="category"
                placeholder="例如：技术、生活、学习"
                value={category}
                onChange={(e) => setCategory(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="content">内容</Label>
              <Textarea
                id="content"
                placeholder="请输入博客内容（支持 Markdown 格式）"
                rows={15}
                value={content}
                onChange={(e) => setContent(e.target.value)}
                required
              />
              <p className="text-sm text-gray-500">支持 Markdown 语法</p>
            </div>

            <div className="space-y-2">
              <Label htmlFor="tags">标签</Label>
              <div className="flex gap-2">
                <Input
                  id="tags"
                  placeholder="输入标签，按 Enter 添加"
                  value={tagInput}
                  onChange={(e) => setTagInput(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      e.preventDefault()
                      handleAddTag()
                    }
                  }}
                />
                <Button type="button" onClick={handleAddTag}>
                  添加
                </Button>
              </div>
              <div className="flex flex-wrap gap-2 mt-2">
                {tags.map(tag => (
                  <Badge key={tag} variant="secondary" className="flex items-center gap-1">
                    {tag}
                    <button
                      type="button"
                      onClick={() => handleRemoveTag(tag)}
                      className="ml-1 hover:text-red-500"
                    >
                      <X size={14} />
                    </button>
                  </Badge>
                ))}
              </div>
            </div>

            <div className="flex items-center space-x-2">
              <input
                type="checkbox"
                id="draft"
                checked={isDraft}
                onChange={(e) => setIsDraft(e.target.checked)}
                className="h-4 w-4"
              />
              <Label htmlFor="draft">保存为草稿</Label>
            </div>
          </CardContent>
          <CardFooter className="flex justify-between">
            <Button type="button" variant="outline" onClick={() => navigate(-1)}>
              取消
            </Button>
            <div className="space-x-2">
