import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Input } from '@/components/ui/input'
import { Pagination, PaginationContent, PaginationItem, PaginationLink, PaginationNext, PaginationPrevious } from '@/components/ui/pagination'
import { Edit, Trash2, Eye, Calendar, User, Tag, BookOpen } from 'lucide-react'

export default function MyBlogs() {
  const [blogs, setBlogs] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)

  const fetchMyBlogs = async () => {
    setLoading(true)
    try {
      // 模拟 API 调用
      await new Promise(resolve => setTimeout(resolve, 500))
      const mockBlogs = Array.from({ length: 8 }).map((_, i) => ({
        id: `${i + 1}`,
        title: `我的博客文章 ${i + 1}`,
        content: `这是第 ${i + 1} 篇博客的内容摘要，这里会显示一些简要的介绍信息。`,
        author: `作者 ${(i % 5) + 1}`,
        createdAt: `2024-01-${String(i + 1).padStart(2, '0')}`,
        tags: ['React', 'TypeScript', '前端'].slice(0, (i % 3) + 1),
        readCount: Math.floor(Math.random() * 1000),
        likeCount: Math.floor(Math.random() * 100),
        commentCount: Math.floor(Math.random() * 50),
        status: i % 3 === 0 ? 'draft' : 'published', // 模拟草稿和已发布
        category: i % 2 === 0 ? '技术' : '生活',
      }))
      setBlogs(mockBlogs)
      setTotalPages(2)
    } catch (error) {
      console.error('获取博客失败:', error)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchMyBlogs()
  }, [page])

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault()
    // 模拟搜索
    fetchMyBlogs()
  }

  const handleDelete = async (id: string) => {
    if (!confirm('确定删除这篇博客吗？')) return
    try {
      // 模拟 API 调用
      await new Promise(resolve => setTimeout(resolve, 300))
      setBlogs(blogs.filter(blog => blog.id !== id))
      alert('删除成功')
    } catch (error) {
      console.error('删除失败:', error)
      alert('删除失败')
    }
  }

  const handlePublish = async (id: string) => {
    try {
      // 模拟 API 调用
      await new Promise(resolve => setTimeout(resolve, 300))
      setBlogs(blogs.map(blog => 
        blog.id === id ? { ...blog, status: 'published' } : blog
      ))
      alert('发布成功')
    } catch (error) {
      console.error('发布失败:', error)
      alert('发布失败')
    }
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="mb-8">
        <h1 className="text-3xl font-bold mb-4">我的博客</h1>
        <p className="text-gray-600 mb-6">
          管理您创建的博客文章，可以编辑、删除或发布草稿。
        </p>
        <div className="flex flex-col md:flex-row justify-between gap-4 mb-6">
          <form onSubmit={handleSearch} className="flex gap-2">
            <Input
              placeholder="搜索博客标题或内容..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="flex-1"
            />
            <Button type="submit">搜索</Button>
          </form>
          <Button asChild>
            <Link to="/blogs/create">创建新博客</Link>
          </Button>
        </div>
      </div>

      {loading ? (
        <div className="text-center py-12">加载中...</div>
      ) : (
        <>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {blogs.map(blog => (
              <Card key={blog.id} className="hover:shadow-lg transition-shadow">
                <CardHeader>
                  <div className="flex justify-between items-start">
                    <div>
                      <CardTitle>
                        <Link to={`/blogs/${blog.id}`} className="hover:text-primary">
                          {blog.title}
                        </Link>
                      </CardTitle>
                      <CardDescription className="flex items-center gap-2 mt-1">
                        <Calendar size={14} />
                        <span>{blog.createdAt}</span>
                        <User size={14} />
                        <span>{blog.author}</span>
                        <BookOpen size={14} />
                        <span>{blog.category}</span>
                      </CardDescription>
                    </div>
                    <Badge variant={blog.status === 'published' ? 'default' : 'secondary'}>
                      {blog.status === 'published' ? '已发布' : '草稿'}
                    </Badge>
                  </div>
                </CardHeader>
                <CardContent>
                  <p className="text-gray-700 line-clamp-2">{blog.content}</p>
                  <div className="flex flex-wrap gap-2 mt-4">
                    {blog.tags.map((tag: string) => (
                      <Badge key={tag} variant="outline" className="flex items-center gap-1">
                        <Tag size={12} />
                        {tag}
                      </Badge>
                    ))}
                  </div>
                </CardContent>
                <CardFooter className="flex justify-between">
                  <div className="flex gap-2 text-sm text-gray-500">
                    <span className="flex items-center gap-1">
                      <Eye size={14} />
                      {blog.readCount} 阅读
                    </span>
                    <span>❤️ {blog.likeCount} 点赞</span>
                    <span>💬 {blog.commentCount} 评论</span>
                  </div>
                  <div className="flex gap-2">
                    <Button variant="outline" size="sm" asChild>
                      <Link to={`/blogs/edit/${blog.id}`}>
                        <Edit size={14} className="mr-1" />
                        编辑
                      </Link>
                    </Button>
                    {blog.status === 'draft' && (
                      <Button variant="default" size="sm" onClick={() => handlePublish(blog.id)}>
                        发布
                      </Button>
                    )}
                    <Button variant="destructive" size="sm" onClick={() => handleDelete(blog.id)}>
                      <Trash2 size={14} className="mr-1" />
                      删除
                    </Button>
                  </div>
                </CardFooter>
              </Card>
            ))}
          </div>

          <div className="mt-8">
            <Pagination>
              <PaginationContent>
                <PaginationItem>
                  <PaginationPrevious 
                    onClick={() => setPage(p => Math.max(1, p - 1))}
                    className={page === 1 ? 'pointer-events-none opacity-50' : ''}
                  />
                </PaginationItem>
                {[...Array(totalPages)].map((_, i) => (
                  <PaginationItem key={i}>
                    <PaginationLink 
                      onClick={() => setPage(i + 1)}
                      isActive={page === i + 1}
                    >
                      {i + 1}
                    </PaginationLink>
                  </PaginationItem>
                ))}
                <PaginationItem>
                  <PaginationNext 
                    onClick={() => setPage(p => p + 1)}
                    className={page === totalPages ? 'pointer-events-none opacity-50' : ''}
                  />
                </PaginationItem>
              </PaginationContent>
            </Pagination>
          </div>
        </>
      )}
    </div>
  )
}

