  onLike?: () => Promise<void>
  className?: string
}

export default function LikeButton({ 
  initialLiked = false, 
  likeCount, 
  onLike,
  className 
}: LikeButtonProps) {
  const [liked, setLiked] = useState(initialLiked)
  const [count, setCount] = useState(likeCount)
