  const handleClick = async () => {
    if (loading) return
    setLoading(true)
    try {
      if (onLike) {
        await onLike()
      }
      const newLiked = !liked
      setLiked(newLiked)
      setCount(prev => newLiked ? prev + 1 : prev - 1)
    } catch (error) {
      console.error('点赞失败:', error)
    } finally {
      setLoading(false)
    }
  }

  return (
    <Button
      variant="ghost"
      size="sm"
      onClick={handleClick}
      disabled={loading}
      className={cn("flex items-center gap-1", className)}
    >
      <Heart 
        className={cn(
          "h-4 w-4",
          liked ? "fill-red-500 text-red-500" : "text-gray-500"
        )} 
      />
      <span>{count}</span>
    </Button>
  )
}

