import { Calendar, Eye, Tag, User, BookOpen, Share2 } from 'lucide-react'

export default function BlogDetail() {
  const { id } = useParams<{ id: string }>()
  const [blog, setBlog] = useState<any>(null)
  const [loading, setLoading] = useState(true)

  const fetchBlog = async () => {
    setLoading(true)
    try {
      // 模拟 API 调用
      await new Promise(resolve => setTimeout(resolve, 500))
      const mockBlog = {
        id: id || '1',
        title: 'React Hooks 深入解析',
        content: `React Hooks 是 React 16.8 引入的一项重大特性，它允许你在函数组件中使用 state 和其他 React 特性。本文将深入探讨常用的 Hooks，包括 useState、useEffect、useContext、useReducer、useCallback、useMemo 等。

## useState
useState 是最基本的 Hook，用于在函数组件中添加状态。

\`\`\`javascript
const [count, setCount] = useState(0);
\`\`\`

## useEffect
useEffect 用于处理副作用，如数据获取、订阅或手动修改 DOM。

\`\`\`javascript
useEffect(() => {
  document.title = \`You clicked \${count} times\`;
}, [count]);
\`\`\`

## useContext
useContext 允许你订阅 React 的 Context 而不需要使用组件树嵌套。

## 自定义 Hooks
通过自定义 Hook，可以将组件逻辑提取到可重用的函数中。

通过合理使用 Hooks，我们可以编写更简洁、可维护的 React 组件。`,
        author: '张三',
        authorAvatar: 'https://github.com/shadcn.png',
        createdAt: '2024-01-15',
        readCount: 1250,
        likeCount: 89,
        favoriteCount: 42,
        commentCount: 24,
        tags: ['React', 'Hooks', '前端', 'JavaScript'],
        category: '技术',
        status: 'published',
      }
      setBlog(mockBlog)
    } catch (error) {
      console.error('获取博客详情失败:', error)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchBlog()
  }, [id])

  const handleLike = async () => {
    // 模拟 API 调用
    await new Promise(resolve => setTimeout(resolve, 300))
    console.log('点赞博客:', id)
  }

  const handleFavorite = async () => {
    // 模拟 API 调用
    await new Promise(resolve => setTimeout(resolve, 300))
    console.log('收藏博客:', id)
  }

  const handleShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: blog?.title,
          text: '分享这篇博客文章',
          url: window.location.href,
        })
      } catch (error) {
        console.error('分享失败:', error)
      }
