                  <span>{blog.createdAt}</span>
                  <Eye size={12} />
                  <span>{blog.readCount} 阅读</span>
                  <BookOpen size={12} />
                  <span>{blog.category}</span>
                </p>
              </div>
            </div>
            <CardTitle className="text-3xl mb-4">{blog.title}</CardTitle>
            <div className="flex flex-wrap gap-2">
