                  initialLiked={false}
                  likeCount={blog.likeCount}
                  onLike={handleLike}
                />
                <FavoriteButton
                  initialFavorited={false}
                  onFavorite={handleFavorite}
                />
                <Button variant="ghost" size="sm" onClick={handleShare}>
                  <Share2 size={16} className="mr-1" />
